validator:
function validate(input) {
  const [{ Employee = [] }] = input;
  const pairs = new Set(), rows = new Map(), yes = new Map();
  for (const [emp, dept, flag] of Employee) {
    if (emp === null || dept === null) return 'employee_id and department_id may not be null.';
    if (flag !== 'Y' && flag !== 'N') return `primary_flag must be 'Y' or 'N', not ${flag}.`;
    const key = `${emp}|${dept}`;
    if (pairs.has(key)) return `Employee ${emp} is in department ${dept} twice.`;
    pairs.add(key);
    rows.set(emp, (rows.get(emp) ?? 0) + 1);
    yes.set(emp, (yes.get(emp) ?? 0) + (flag === 'Y' ? 1 : 0));
  }
  for (const [emp, count] of rows) {
    if (count === 1 && yes.get(emp) !== 0) return `Employee ${emp} has one department, so its flag must be 'N'.`;
    if (count > 1 && yes.get(emp) !== 1) return `Employee ${emp} has several departments and needs exactly one 'Y'.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = (n) => Math.floor(rand() * n);
  const limit = small ? pick(9) : 2000;
  const depts = small ? 4 : 20;
  const Employee = [];
  for (let emp = 1 + pick(3); Employee.length < limit; emp += 1 + (small ? pick(3) : 0)) {
    // Choose 1 to 3 (small) or 1 to 4 (large) distinct departments, trimmed to the row budget.
    const want = Math.min(1 + pick(small ? 3 : 4), limit - Employee.length);
    const chosen = new Set();
    while (chosen.size < want) chosen.add(1 + pick(depts));
    const list = [...chosen];
    const primary = list.length > 1 ? pick(list.length) : -1;
    list.forEach((dept, i) => Employee.push([emp, dept, i === primary ? 'Y' : 'N']));
  }
  for (let i = Employee.length - 1; i > 0; i--) { const j = pick(i + 1); [Employee[i], Employee[j]] = [Employee[j], Employee[i]]; }
  return [{ Employee }];
}
